// Typed access to packages/shared/fixtures/*.json (generated by scripts/gen-fixtures.ts).
// Every file is parsed through its zod schema, so a fixture that drifts from the spec fails loudly.

import { z } from "zod";
import decisionsJson from "../fixtures/decisions.json";
import eventsJson from "../fixtures/events.json";
import leaderboardJson from "../fixtures/leaderboard.json";
import playersJson from "../fixtures/players.json";
import worldJson from "../fixtures/world.json";
import { DecisionSchema, EventSchema, LeaderboardRowSchema, PlayerSchema, WorldStateSchema } from "./schemas.js";

export const PlayersFixtureSchema = z.object({
  newPlayerInBandar: PlayerSchema,
  midJourney: PlayerSchema,
  ambushResult: PlayerSchema,
}).strict();

export const LeaderboardFixtureSchema = z.object({ rows: z.array(LeaderboardRowSchema) }).strict();

export const worldFixture = WorldStateSchema.parse(worldJson);
export const playersFixture = PlayersFixtureSchema.parse(playersJson);
export const eventsFixture = z.array(EventSchema).parse(eventsJson);
export const leaderboardFixture = LeaderboardFixtureSchema.parse(leaderboardJson);
export const decisionsFixture = z.array(DecisionSchema).parse(decisionsJson);
